import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    max_nodes = N // 2 + 1
    fact = [1] * (max_nodes + 1)
    invfact = [1] * (max_nodes + 1)

    for i in range(1, max_nodes + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact[max_nodes] = pow(fact[max_nodes], MOD - 2, MOD)
    for i in range(max_nodes, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    class_id = {}
    class_count = []

    def forest_count(children):
        children = tuple(sorted(children))
        k = len(children)
        res = fact[k]

        i = 0
        while i < k:
            j = i + 1
            while j < k and children[j] == children[i]:
                j += 1

            multiplicity = j - i
            cid = children[i]
            res = res * invfact[multiplicity] % MOD
            res = res * pow(class_count[cid], multiplicity, MOD) % MOD
            i = j

        return res

    def get_class(children):
        key = tuple(sorted(children))
        if key in class_id:
            return class_id[key]

        cid = len(class_count)
        class_id[key] = cid
        class_count.append(forest_count(key))
        return cid

    stack = [[]]

    for ch in S:
        if ch == '(':
            stack.append([])
        else:
            children = stack.pop()
            cid = get_class(children)
            stack[-1].append(cid)

    print(forest_count(stack[0]))

if __name__ == "__main__":
    main()
